.darma-loader-darma-b10-carousel-dots-3d { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 88px); height: var(--loader-size, 88px); display: grid; place-items: center; perspective: 600px; }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring { position: relative; width: 70%; height: 70%; transform-style: preserve-3d; animation: darma-loader-darma-b10-carousel-dots-3d-carousel calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span { position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size, 88px) * .13); height: calc(var(--loader-size, 88px) * .13); margin: calc(var(--loader-size, 88px) * -.065) 0 0 calc(var(--loader-size, 88px) * -.065); border-radius: 50%; background: var(--accent); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(even) { background: var(--accent-2); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(1) { transform: rotateY(0deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(2) { transform: rotateY(45deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(3) { transform: rotateY(90deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(4) { transform: rotateY(135deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(5) { transform: rotateY(180deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(6) { transform: rotateY(225deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(7) { transform: rotateY(270deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
.darma-loader-darma-b10-carousel-dots-3d .darma-loader-darma-b10-carousel-dots-3d__ring span:nth-child(8) { transform: rotateY(315deg) translateZ(calc(var(--loader-size, 88px) * .32)); }
@keyframes darma-loader-darma-b10-carousel-dots-3d-carousel { to { transform: rotateY(360deg); } }

